import{_ as n,C as o,o as t,c as s,a2 as a,b as c,w as r,a as d,E as l,a3 as h}from"./chunks/framework.Dd_iHz3e.js";const _=JSON.parse('{"title":"14.12 Search & AI Integration Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.12-search-and-ai-architecture.md","filePath":"system-design/14.12-search-and-ai-architecture.md"}'),u={name:"system-design/14.12-search-and-ai-architecture.md"};function m(g,e,p,S,v,f){const i=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="_14-12-search-ai-integration-architecture" tabindex="-1">14.12 Search &amp; AI Integration Architecture <a class="header-anchor" href="#_14-12-search-ai-integration-architecture" aria-label="Permalink to &quot;14.12 Search &amp; AI Integration Architecture&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Search and AI architecture manages how users discover content (lexical text indexing vs semantic vector similarity) and how generative AI models are prompted, streamed, cached, and guarded to deliver accurate answers with minimal cost and latency.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>AI Streaming Gateway</strong>: Google&#39;s Gemini 3 Flash model via Lovable AI Gateway with Server-Sent Events ([chef-ai/index.ts](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/supabase/functions/chef-ai/index.ts), [ai-stream.ts](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/src/lib/ai-stream.ts)).</li><li><strong>Prompt Personas</strong>: Conversational Chef (<code>chat</code>), Theatrical Comparative Gastronomy (<code>ghostchef</code>), Structured JSON Extraction (<code>import</code>).</li><li><strong>Global Search</strong>: [src/pages/GlobalSearchPage.tsx](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/src/pages/GlobalSearchPage.tsx) indexing dishes, chefs, tags, and preparation times.</li></ul><hr><h2 id="_3-semantic-vector-search-ai-pipeline-architecture" tabindex="-1">3. Semantic Vector Search &amp; AI Pipeline Architecture <a class="header-anchor" href="#_3-semantic-vector-search-ai-pipeline-architecture" aria-label="Permalink to &quot;3. Semantic Vector Search &amp; AI Pipeline Architecture&quot;">​</a></h2>',8)),(t(),c(h,null,{default:r(()=>[l(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20UserQuery%5B%22User%3A%20'Warm%20soup%20for%20a%20rainy%20cold%20day'%22%5D%20--%3E%20Embedder%5B%22Embedding%20Model%20(text-embedding-3-small)%22%5D%0A%20%20%20%20Embedder%20--%3E%7C1536-dimensional%20Vector%7C%20VectorStore%5B(%22Atlas%20Vector%20Search%20%2F%20Pinecone%22)%5D%0A%20%20%20%20VectorStore%20--%3E%7CCosine%20Similarity%20K%3D5%7C%20RetrievedDocs%5B%22Retrieved%20Recipes%3A%20Miso%20Ramen%2C%20French%20Onion%2C%20Butternut%20Squash%22%5D%0A%20%20%20%20RetrievedDocs%20--%3E%20PromptBuilder%5B%22Prompt%20Context%20Builder%22%5D%0A%20%20%20%20PromptBuilder%20--%3E%20GeminiLLM%5B%22Gemini%203%20Flash%20Preview%22%5D%0A%20%20%20%20GeminiLLM%20--%3E%7CStream%20Tokens%7C%20SSEOutput%5B%22text%2Fevent-stream%20to%20React%20SPA%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_4-search-architecture-comparison" tabindex="-1">4. Search Architecture Comparison <a class="header-anchor" href="#_4-search-architecture-comparison" aria-label="Permalink to &quot;4. Search Architecture Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Search Engine</th><th>Mechanism</th><th>Query Type</th><th>Latency</th><th>Infrastructure Overhead</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>MongoDB Text Index</strong></td><td>Inverted Index (BM25)</td><td>Exact word matches, stemming</td><td>Low (Local DB index)</td><td>Zero extra infrastructure</td><td>Ideal for MVP recipe titles</td></tr><tr><td><strong>Atlas Vector Search (Target)</strong></td><td>HNSW Vector Embeddings</td><td>Semantic meaning &amp; intent</td><td>Moderate (~25ms)</td><td>Integrated in MongoDB</td><td>Optimal for semantic recipe discovery</td></tr><tr><td><strong>Elasticsearch / OpenSearch</strong></td><td>Distributed Lucene Cluster</td><td>Full-text, fuzzy, aggregations</td><td>Low-Moderate</td><td>High (Dedicated JVM cluster)</td><td>Overkill for early stage</td></tr><tr><td><strong>Algolia / Meilisearch</strong></td><td>Hosted Instant Search API</td><td>Typo-tolerant prefix search</td><td>Ultra-Low (&lt;10ms)</td><td>Managed Cloud API</td><td>Great, but high SaaS cost at scale</td></tr><tr><td><strong>Pinecone</strong></td><td>Dedicated Vector SaaS</td><td>High-dimensional k-NN</td><td>Low</td><td>Managed SaaS API</td><td>Good alternative to Atlas Vector</td></tr></tbody></table><hr><h2 id="_5-structured-output-hallucination-mitigation" tabindex="-1">5. Structured Output &amp; Hallucination Mitigation <a class="header-anchor" href="#_5-structured-output-hallucination-mitigation" aria-label="Permalink to &quot;5. Structured Output &amp; Hallucination Mitigation&quot;">​</a></h2><ol><li><strong>JSON Schema Injection</strong>: In <code>import</code> mode, the prompt enforces a rigid JSON schema specifying mandatory integer fields for <code>prep_time</code> and <code>servings</code>.</li><li><strong>Grounding via Retrieval-Augmented Generation (RAG)</strong>: Rather than asking the LLM to invent an obscure Thai curry recipe from memory, the system retrieves verified culinary ingredient ratios from the database and injects them as grounding context.</li></ol><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: LLM cost spikes during viral user influxes if common queries (&quot;substitute butter&quot;) are not cached.</li><li><strong>At 100x</strong>: Vector embedding API rate limits when generating embeddings for thousands of newly uploaded creator recipes.</li><li><strong>At 1,000x</strong>: Context window memory bloat if full recipe histories are fed into chat context without conversational summarization.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><p>Implement a <strong>Semantic Redis Cache with Cosine Similarity</strong>: Before calling Gemini 3 Flash, compute the vector embedding of the user&#39;s question and query Redis with <code>FT.SEARCH</code>. If a prior query has a cosine similarity $&gt; 0.96$, return the cached response immediately, slashing LLM API costs by up to 70%.</p><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;Our AI architecture combines Server-Sent Events streaming with prompt persona routing. To deliver sub-second culinary intelligence without hallucinations, we use Gemini 3 Flash for zero-shot recipe parsing and conversational substitutions, with strict system prompt guardrails. As our recipe catalogue scales, we plan to implement a RAG pipeline using Atlas Vector Search to retrieve verified ingredient ratios, ensuring our generative sous chef always grounds its answers in culinary facts.&quot;</p>',15))])}const b=n(u,[["render",m]]);export{_ as __pageData,b as default}